def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    # Count behaviors
    coop = 0
    defd = 0
    for h in history:
        if h[1] == 'C':
            coop += 1
        else:
            defd += 1

    # Last few opponent moves
    tail = history[-min(5, n):]
    tail_c = 0
    tail_d = 0
    for h in tail:
        if h[1] == 'C':
            tail_c += 1
        else:
            tail_d += 1

    # If opponent is nearly always defecting, defect.
    if defd >= 3 and defd * 2 > coop:
        return 'D'

    # If opponent is highly cooperative, cooperate, with a little probing near the end.
    if coop >= 3 and coop * 2 >= defd * 3:
        if n >= 90 and rng.random() < 0.08:
            return 'D'
        return 'C'

    # Tit-for-tat-ish with forgiveness on last move.
    if n > 0:
        last_opp = history[-1][1]
        if last_opp == 'D':
            # Forgive occasionally if previous was cooperative and opponent has cooperated before.
            if tail_d <= 1 and coop >= 2 and rng.random() < 0.12:
                return 'C'
            return 'D'
        else:
            # Opponent cooperated last; sometimes defect late for payoff, otherwise cooperate.
            if n >= 85 and rng.random() < 0.06:
                return 'D'
            return 'C'

    return 'C'
