def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    coop = 0
    defd = 0
    for h in history:
        if h[1] == 'C':
            coop += 1
        else:
            defd += 1

    tail = history[-min(5, n):]
    tail_c = 0
    tail_d = 0
    for h in tail:
        if h[1] == 'C':
            tail_c += 1
        else:
            tail_d += 1

    if defd >= 3 and defd * 2 > coop:
        return 'D'

    if coop >= 3 and coop * 2 >= defd * 3:
        if n >= 90 and rng.random() < 0.08:
            return 'D'
        return 'C'

    if n > 0:
        last_opp = history[-1][1]
        if last_opp == 'D':
            if tail_d <= 1 and coop >= 2 and rng.random() < 0.12:
                return 'C'
            return 'D'
        else:
            if n >= 85 and rng.random() < 0.06:
                return 'D'
            return 'C'

    return 'C'
